export function translateOfflineText(source: string, locale: string) {
  const normalizedLocale = locale.toLowerCase().startsWith('zh') ? 'zh-CN' : locale
  const text = source.trim()
  const exact = catalogs[normalizedLocale]?.get(text)
  if (exact) return exact
  for (const template of [...(dynamicTemplates[normalizedLocale] ?? []), ...(additionalDynamicTemplates[normalizedLocale] ?? [])]) {
    const match = text.match(template.pattern)
    if (match) return template.render(match)
  }
  return null
}
